// Contract test: the firmware's reply parser vs. REAL replies captured from the gateway
// (fixtures regenerated by tools/gen_contract_fixtures.py), plus hostile inputs.
#include <stdio.h>
#include <string.h>
#include <unity.h>

#include <fstream>
#include <sstream>
#include <string>

#include "gateway_reply.h"
#include "utf8.h"

using namespace robot;

static std::string fixture(const char* name) {
  const char* dirs[] = {"test/test_gateway_contract/fixtures/", "fixtures/", "../test/test_gateway_contract/fixtures/"};
  for (const char* d : dirs) {
    std::ifstream f(std::string(d) + name);
    if (f) {
      std::stringstream ss;
      ss << f.rdbuf();
      return ss.str();
    }
  }
  TEST_FAIL_MESSAGE(name);
  return "";
}

struct Parsed {
  bool ok;
  GatewayReply r;
  char path[96];
  uint32_t rate;
};

static Parsed parse(const std::string& body) {
  Parsed p;
  p.ok = parseGatewayReply(body.data(), body.size(), p.r, p.path, sizeof(p.path), p.rate);
  return p;
}

void setUp() {}
void tearDown() {}

void test_math_en() {
  Parsed p = parse(fixture("math_en.json"));
  TEST_ASSERT_TRUE(p.ok);
  TEST_ASSERT_FALSE(p.r.ignore);
  TEST_ASSERT_EQUAL((int)ContentKind::Math, (int)p.r.contentKind);
  TEST_ASSERT_EQUAL_STRING("7 + 5 = 12", p.r.contentValue);
  TEST_ASSERT_EQUAL_STRING("7 + 5 = 12", p.r.oledText);
  TEST_ASSERT_TRUE(p.r.hasAudio);
  TEST_ASSERT_EQUAL_UINT32(16000, p.rate);
  TEST_ASSERT_EQUAL_INT(0, strncmp(p.path, "/v1/turns/", 10));
  TEST_ASSERT_EQUAL((int)Expression::Happy, (int)p.r.emotion);
}

void test_math_ar() {
  Parsed p = parse(fixture("math_ar.json"));
  TEST_ASSERT_TRUE(p.ok);
  TEST_ASSERT_EQUAL_STRING("6 x 7 = 42", p.r.contentValue);
  TEST_ASSERT_EQUAL_STRING("ar", p.r.lang);
}

void test_alphabet_en_and_ar() {
  Parsed en = parse(fixture("alphabet_en.json"));
  TEST_ASSERT_TRUE(en.ok);
  TEST_ASSERT_EQUAL((int)ContentKind::Letter, (int)en.r.contentKind);
  TEST_ASSERT_EQUAL_STRING("A", en.r.contentValue);
  TEST_ASSERT_EQUAL_STRING("Apple", en.r.contentCaption);
  Parsed ar = parse(fixture("alphabet_ar.json"));
  TEST_ASSERT_TRUE(ar.ok);
  TEST_ASSERT_TRUE(ar.r.rtl);
  TEST_ASSERT_EQUAL_STRING("ﺏ", ar.r.contentValue);  // ب, isolated presentation form
  TEST_ASSERT_TRUE(utf8IsValid(ar.r.contentCaption));
}

void test_long_arabic_story_fits_buffers() {
  Parsed p = parse(fixture("story_ar.json"));
  TEST_ASSERT_TRUE(p.ok);
  TEST_ASSERT_TRUE(p.r.rtl);
  TEST_ASSERT_TRUE(strlen(p.r.oledText) > 0 && strlen(p.r.oledText) <= kMaxTextBytes);
  TEST_ASSERT_TRUE(utf8IsValid(p.r.oledText));
  TEST_ASSERT_TRUE(fixture("story_ar.json").size() < 8192);  // firmware's maximum reply size
}

void test_vocab_word_card() {
  Parsed p = parse(fixture("vocab_ar.json"));
  TEST_ASSERT_TRUE(p.ok);
  TEST_ASSERT_EQUAL((int)ContentKind::Word, (int)p.r.contentKind);
}

void test_ignore_and_demo() {
  Parsed ig = parse(fixture("ignore.json"));
  TEST_ASSERT_TRUE(ig.ok);
  TEST_ASSERT_TRUE(ig.r.ignore);
  TEST_ASSERT_FALSE(ig.r.hasAudio);
  Parsed d = parse(fixture("demo_audio.json"));
  TEST_ASSERT_TRUE(d.ok);
  TEST_ASSERT_TRUE(d.r.hasAudio);
  TEST_ASSERT_EQUAL((int)Expression::Surprised, (int)d.r.emotion);
}

void test_text_mode_replies_carry_full_answer_without_audio() {
  const char* files[] = {"textmode_story_en.json", "textmode_story_ar.json", "textmode_math_ar.json"};
  for (const char* f : files) {
    Parsed p = parse(fixture(f));
    TEST_ASSERT_TRUE_MESSAGE(p.ok, f);
    TEST_ASSERT_FALSE_MESSAGE(p.r.hasAudio, f);  // no speaker: nothing to stream
    TEST_ASSERT_TRUE_MESSAGE(strlen(p.r.longText) > 20, f);
    TEST_ASSERT_TRUE(strlen(p.r.longText) <= kMaxLongTextBytes);
    TEST_ASSERT_TRUE(utf8IsValid(p.r.longText));
  }
  TEST_ASSERT_TRUE(parse(fixture("textmode_story_ar.json")).r.longRtl);
  TEST_ASSERT_FALSE(parse(fixture("textmode_story_en.json")).r.longRtl);
}

void test_hostile_audio_urls_rejected() {
  const char* bodies[] = {
      R"({"display":{},"audio":{"path":"https://evil.example/a","format":"pcm_s16le","sample_rate":16000}})",
      R"({"display":{},"audio":{"path":"//evil.example/v1/a","format":"pcm_s16le","sample_rate":16000}})",
      R"({"display":{},"audio":{"path":"/v1/../../etc","format":"pcm_s16le","sample_rate":16000}})",
      R"({"display":{},"audio":{"path":"/v1/a?x=1","format":"pcm_s16le","sample_rate":16000}})",
      R"({"display":{},"audio":{"path":"/v1/a","format":"mp3","sample_rate":16000}})",
      R"({"display":{},"audio":{"path":"/v1/a","format":"pcm_s16le","sample_rate":96000}})",
  };
  for (const char* b : bodies) {
    Parsed p = parse(b);
    TEST_ASSERT_TRUE(p.ok);
    TEST_ASSERT_FALSE_MESSAGE(p.r.hasAudio, b);
    TEST_ASSERT_EQUAL_STRING("", p.path);
  }
}

void test_hostile_fields_sanitised() {
  Parsed p = parse(R"({"emotion":"error","display":{"content":{"kind":"video","value":"x"}}})");
  TEST_ASSERT_TRUE(p.ok);
  TEST_ASSERT_EQUAL((int)Expression::Happy, (int)p.r.emotion);  // only allow-listed emotions
  TEST_ASSERT_EQUAL((int)ContentKind::None, (int)p.r.contentKind);
  std::string big = R"({"display":{"oled_text":")" + std::string(5000, 'a') + R"("}})";
  Parsed q = parse(big);
  TEST_ASSERT_TRUE(q.ok);
  TEST_ASSERT_EQUAL((int)kMaxTextBytes, (int)strlen(q.r.oledText));
  TEST_ASSERT_FALSE(parse("[1,2,3]").ok);
  TEST_ASSERT_FALSE(parse("{not json").ok);
  TEST_ASSERT_FALSE(parse("{\"display\":{\"oled_text\":\"\xC3\x28\"}}").ok);  // invalid UTF-8
}

int main() {
  UNITY_BEGIN();
  RUN_TEST(test_math_en);
  RUN_TEST(test_math_ar);
  RUN_TEST(test_alphabet_en_and_ar);
  RUN_TEST(test_long_arabic_story_fits_buffers);
  RUN_TEST(test_vocab_word_card);
  RUN_TEST(test_ignore_and_demo);
  RUN_TEST(test_text_mode_replies_carry_full_answer_without_audio);
  RUN_TEST(test_hostile_audio_urls_rejected);
  RUN_TEST(test_hostile_fields_sanitised);
  return UNITY_END();
}
